// Clasifica cada negocio por el nombre del anuncio/creativo de origen.
// AJUSTAR el campo real una vez confirmado con un negocio de prueba real
// (hipotesis: Business.name o un additionalInfo — no se confirmo esta noche,
// ver seccion 1.1 de 31-pipeline-masivo-y-api-negocios-2026-09-19.md).

const REGLAS = [
  { match: /creatina/i, columna: 'CAMPAÑA CREATINA' },
  { match: /testo/i, columna: 'CAMPAÑA TESTO DILATED' },
  { match: /hipercalor/i, columna: 'CAMPAÑA HIPERCALORICO' },
  { match: /isolad|isolate/i, columna: 'CAMPAÑA ISOLADO' },
  { match: /woman|femenin|mujer/i, columna: 'CAMPAÑA WOMAN' },
];

const out = [];
const sinClasificar = [];

for (const item of $input.all()) {
  const negocio = item.json;
  // AJUSTAR: reemplazar por el campo real donde vive el nombre del anuncio.
  const textoOrigen = negocio.adName || negocio.Business?.name || negocio.title || '';

  const regla = REGLAS.find(r => r.match.test(textoOrigen));

  if (regla) {
    out.push({ json: { id: negocio.id, targetStep: regla.columna, textoOrigen } });
  } else {
    sinClasificar.push({ json: { id: negocio.id, textoOrigen, motivo: 'sin match en las reglas' } });
  }
}

// Los sin clasificar se devuelven aparte para revision manual, NUNCA se mueven a ciegas.
return { clasificados: out, sinClasificar };
